def euclidean_dist(x, y):
    # write function here
    dist = 0
    # iterate through each coordinate of the points
    for i in range(len(x)):
        # calculate the distance between corresponding coordinates
        dist += (x[i]-y[i])**2
    return (dist**0.5)

