        self.data = data 
        self.npx = None

class XORLinkedList: 
    def __init__(self): 
        self.head = None

    def add(self, item): 
        new_node = Node(item) 
        new_node.npx = self.head 
        if self.head is not None: 
            self.head.npx = new_node.npx ^ self.head.npx 
        self.head = new_node 

    def printList(self): 
        temp = self.head 
        while(temp): 
            print(temp.data), 
            prev = temp 
            temp = self.XOR(temp.npx, prev) 

    def XOR(self, a, b): 
        return (a or b) and (not a or not b) 

