def find_primes(num):
    """Find all the prime numbers less than or equal to a given number."""
    primes = []
    for i in range(2, num + 1):
        is_prime = True
        for j in range(2, int(i ** 0.5) + 1):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(i)
    return primes

def contains_cycle(head):
    slow = head
    fast = head
    while fast is not None and fast.next is not None:
        fast = fast.next.next
        slow = slow.next
        if slow is fast:
            return True
    return False

def find_primes_below(n):
    """This function finds all prime numbers between 2 and a given integer"""
    primes = [True] * n
    primes[0], primes[1] = False, False

    # Find prime numbers
    for i, is_prime in enumerate(primes):
      if is_prime:
        for num in range(i*i, n, i):
            primes[num] = False

    # Filter out primes
    return [i for i, prime in enumerate(primes) if prime]

