def binary_search(list, target):
    low = 0
    high = len(list)-1
    while low <= high:
        mid = (low + high) // 2
        if list[mid] == target:
            return mid
        if list[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

from math import sqrt

def prime_numbers(n):
    primes = []
    i = 2
    while len(primes) < n:
        for number in range(2, int(sqrt(i)) + 1):
            if i % number == 0:
                break
        else:
            primes.append(i)
        i += 1
    yield from primes

