def findLongestSubsequence(arr): 
    n = len(arr)
    dp = [1]*n 
    for i in range(1, n): 
        for j in range(i): 
            if arr[i] > arr[j] and dp[i] < dp[j] + 1 : 
                dp[i] = dp[j]+1
    return max(dp)

