def quicksort(alist):
    quicksort_helper(alist, 0, len(alist)-1)

def quicksort_helper(alist, first, last):
    if first < last:
        splitpoint = partition(alist, first, last)
        quicksort_helper(alist, first, splitpoint-1)
        quicksort_helper(alist, splitpoint+1, last)

def partition(alist, first, last):
    pivot = alist[first]

    leftmark = first+1
    rightmark = last

    done = False
    while not done:
        while leftmark <= rightmark and alist[leftmark] <= pivot:
            leftmark = leftmark + 1

        while alist[rightmark] >= pivot and rightmark >= leftmark:
            rightmark = rightmark - 1

        if rightmark < leftmark:
            done = True
        else:
            temp = alist[leftmark]
            alist[leftmark] = alist[rightmark]
            alist[rightmark] = temp

    temp = alist[first]
    alist[first] = alist[rightmark]
    alist[rightmark] = temp

    return rightmark

# Bubble Sort algorithm
def bubble_sort(lst):
    for i in range(len(lst)-1):
        for j in range(len(lst)-1-i):
            if lst[j] > lst[j+1]:
                lst[j], lst[j+1] = lst[j+1], lst[j]
    return lst

# Insertion Sort algorithm
def insertion_sort(lst):
    for i in range(1, len(lst)):
        key = lst[i]
        j = i - 1
        while j >= 0 and key < lst[j]:
            lst[j+1] = lst[j]
            j -= 1
        lst[j+1] = key
    return lst

# Heap Sort algorithm
def heap_sort(lst):
    # build max heap
    for i in range(len(lst) // 2 - 1, -1, -1):
        heapify(lst, len(lst), i)

    # extract elements
    for i in range(len(lst) - 1, 0, -1):
        lst[i], lst[0] = lst[0], lst[i]
        heapify(lst, i, 0)
    return lst

def heapify(lst, n, i):
    # Find largest among root, left child and right child
    largest = i 
    l = 2 * i + 1
    r = 2 * i + 2 

    if l < n and lst[i] < lst[l]:
        largest = l

    if r < n and lst[largest] < lst[r]:
        largest = r

    # change root, if needed
    if largest != i:
        lst[i], lst[largest] = lst[largest], lst[i]
        heapify(lst, n, largest)

