def passwordGenerator(length):
    str = string.ascii_uppercase + string.ascii_lowercase + string.digits
    passwd = "".join(random.choice(str) for x in range(length))
    if (any(x.isupper() for x in passwd) and any(x.islower() for x in passwd) and any(x.isdigit() for x in passwd)): 
        return passwd
    else:
        return passwordGenerator(length)

