def insert(self,val): 
	if not self.root: 
		self.root = Node(val) 
	else: 
		current = self.root
		while True: 
			if val < current.val: 
				if current.left: 
					current = current.left 
				else: 
					current.left = Node(val) 
					break
			elif val > current.val: 
				if current.right: 
