solution:
class Example:
    def __init__(self, x, y):
        self.__x = x
        self.__y = y
    @property
    def x(self):
        return self.__x
    @x.setter
    def x(self, val):
        raise AttributeError("Cannot modify x")
    @property
    def y(self):
        return self.__y
    @y.setter
    def y(self, val):
        raise AttributeError("Cannot modify y")

