question:
Create a tree structure using the provided Python dictionary.
dict = {
  1: {
    'parent': 0,
    'children': [2, 3, 4]
  },
  2: {
    'parent': 1,
    'children': []
  },
  3: {
    'parent': 1,
    'children': [5, 6]
  },
  4: {
    'parent': 1,
    'children': [7]
  },
  5: {
    'parent': 3,
    'children': []
  },
  6: {
    'parent': 3,
    'children': []
  }
  7: {
    'parent': 4,
    'children': []
  }
}

solution:
"""
Create a tree structure using the Python dictionary provided
"""

class TreeNode:
    def __init__(self, value=None, parent=None, children=None):
        self.value = value
        self.parent = parent
        self.children = children if children is not None else []

    def __repr__(self):
        return f"TreeNode({self.value}, {self.parent.value}, {[c.value for c in self.children]})"

    def __str__(self):
        return self.__repr__()

def create_tree_structure(data):
    tree = dict()
    for k, v in data.items():
        parent = v["parent"]
        tree[k] = TreeNode(value=k, parent=tree.get(parent), children=list())
        if parent in tree:
            tree[parent].children.append(tree[k])
    return tree

