def find_median(list_of_numbers):
    sorted_list = sorted(list_of_numbers)
    length = len(sorted_list)
    if length % 2 == 0:
        median1 = sorted_list[length // 2]
        median2 = sorted_list[(length // 2) - 1]
        median = (median1 + median2) / 2
    else:
        median = sorted_list[length // 2]
